### **Question 2:** Job Scheduling with Minimum Maximum Load  
**Problem Statement:**  
You are given an array of jobs where `jobs[i]` represents the time required to complete a job. Distribute these jobs among `k` workers such that the maximum time taken by any worker is minimized.  

**Test Cases:**  
Input 1:  
```
3  
3 2 3  
3  
```
Output 1:  
```
3  
```

Input 2:  
```
5  
1 2 4 7 8  
2  
```
Output 2:  
```
11  
```

**Code:**  
```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;cin>>n;
    vector<int> v(n,0);
    for(int i=0;i<n;i++){ cin>>v[i];}
    int k;cin>>k;
    int temp=k;
    if(k>=v.size()) {cout<<*max_element(v.begin(),v.end());return 0;}
    priority_queue<int,vector<int>,greater<int>> pq;
    sort(v.begin(),v.end());
    int idx;
    for(int i=n-1;i>=0&&temp>0;i--) {
        pq.push(v[i]);
        temp--;
        idx=i;
    }
    for(int i=idx-1;i>=0;i--){
        int x= pq.top();
        pq.pop();
        x+=v[i];
        pq.push(x);
    }
    int maxx=INT_MIN;
    // for(auto x:pq) maxx=max(maxx,x);
    while(!pq.empty()){
        maxx=max(maxx,pq.top());
        pq.pop();
    }
    cout<<maxx<<"\n";
    return 0;
}
```  

